  return {
    profile: "dev",
    runtimes: {
      claude: { command: "claude", argsTemplate: [] },
      gemini: { command: "gemini", argsTemplate: [] },
      openclaw: { command: "openclaw", argsTemplate: [] },
      mock: { command: "node", argsTemplate: ["-e", '{"claimedLevels":{}}'] },
      any: { command: "", argsTemplate: [] }
    },
    security: {
      trustBoundaryMode: "shared",
      durability: "crash"
    },
    supervise: {
      extraEnv: {},
      includeProxyEnv: true,
      customBaseUrlEnvKeys: []
    }
  };
}

export function expandEnvTemplate(input: string, env: NodeJS.ProcessEnv = process.env): string {
  return input.replace(/\$\{([A-Z0-9_]+)(:-([^}]*))?\}/gi, (_all, key: string, _fallback: string | undefined, defaultValue: string | undefined) => {
    const value = env[key];
    if (typeof value === "string" && value.length > 0) {
      return value;
    }
    return defaultValue ?? "";
  });
}

export function loadGatewayConfigFromPath(configPath: string): GatewayConfig {
  if (!pathExists(configPath)) {
    throw new Error(`Gateway config not found: ${configPath}`);
  }
  const parsed = YAML.parse(readFileSync(configPath, "utf8")) as unknown;
  return gatewayConfigSchema.parse(parsed);
}

export function buildRollbackLifecycleReceipt(input: {
  workspace: string;
  agentId: string;
  command: string;
  targetManifestId: string;
  restoreReceiptPath: string | null;
  reason: string;
  refs?: string[];
}): LifecycleChangeReceipt {
  const now = new Date().toISOString();
  return {
    schemaVersion: "2026-05-22",
    receiptId: `lifecycle-rollback-${Date.now()}`,
    receiptType: "rollback",
    status: "rolled-back",
    runId: null,
    lifecycleRunId: null,
    agentId: input.agentId,
    workspace: resolve(input.workspace),
    command: input.command,
    createdAt: now,
    subject: {
      resourceManifestIds: [input.targetManifestId],
      decisionReceiptIds: [],
      findingProofSetIds: [],
      rollbackTargetManifestId: input.targetManifestId
    },
    policyChecks: [{
      policyId: "rollback-target-manifest-present",
      passed: Boolean(input.targetManifestId),
      summary: "Rollback points to an exact Enforce resource manifest.",
      evidenceRefs: [input.targetManifestId]
    }],
    evaluationEvidence: {
      diagnosticRunId: null,
      diagnosticStatus: null,
      evidenceStatus: null,
      claimEligible: false,
      integrityIndex: null,
      evidenceCoverage: null
    },
    rollback: {
      targetManifestId: input.targetManifestId,
      restoreReceiptPath: input.restoreReceiptPath,
      reason: input.reason
    },
    monitor: {
      health: "unknown",
      driftState: "unknown",
      summary: "Run a fresh full score after rollback to record post-change health."
    },
    refs: input.refs ?? []
  };
}

export function buildObservabilityLaneRecord(input: WriteObservabilityLaneInput): ObservabilityLaneRecord {
  const workspace = resolve(input.workspace);
  const report = input.report;
  const componentAttribution = [
    ...buildQuestionComponents(report),
    ...buildResourceComponents(input.resourceManifests),
    ...buildDecisionComponents(input.decisionReceipts)
  ];
  const experienceCorpus = buildExperienceCorpus(input);
  const decisionChain = buildDecisionChain(input.decisionReceipts);
  const observedDecisionCount = decisionChain.filter((entry) => entry.status === "observed").length;
  const proposedDecisionCount = decisionChain.filter((entry) => entry.status === "proposed").length;
  const highRiskComponentCount = componentAttribution.filter((component) => component.risk === "critical" || component.risk === "high").length;

  return {
    schemaVersion: "2026-05-22",
    observabilityId: `observability-${report.runId}`,
    runId: report.runId,
    lifecycleRunId: `lifecycle-${report.runId}`,
    agentId: report.agentId,
    workspace,
    source: input.source,
    command: input.command,
    createdAt: new Date(report.ts).toISOString(),
    surfaces: ["Score", "Watch", "Vault"],
    episodeIds: input.episodeIds ?? [],
    lifecycleReceiptIds: input.lifecycleReceiptIds ?? [],
    resourceManifestIds: (input.resourceManifests ?? []).map((ref) => ref.manifestId),
    componentAttribution,
    experienceCorpus,
    decisionChain,
    observedDecisionReceiptIds: input.observedDecisionReceiptIds ?? [],
    summary: {
      componentCount: componentAttribution.length,
      highRiskComponentCount,
      experienceSignalCount: experienceCorpus.length,
      decisionCount: decisionChain.length,
      proposedDecisionCount,
      observedDecisionCount
    }
  };
}

