export function authorizeExploitConfirmation(input: {
  workspace: string;
  scope: ExploitConfirmationScope | null;
  task: ExploitConfirmationTask;
  nowTs?: number;
}): ExploitConfirmationAuthorization {
  const reasons: string[] = [];
  const nowTs = input.nowTs ?? Date.now();
  const scope = input.scope;
  if (!scope) {
    return {
      ok: false,
      scopeId: null,
      reasons: ["MISSING_EXPLICIT_AUTHORIZATION_SCOPE"]
    };
  }
  if (!scope.target.ownership.attested) {
    reasons.push("TARGET_OWNERSHIP_NOT_ATTESTED");
  }
  if (nowTs < scope.windowStartTs || nowTs > scope.windowEndTs) {
    reasons.push("AUTHORIZATION_WINDOW_INACTIVE");
  }
  if (!scope.allowedTechniques.includes(input.task.technique)) {
    reasons.push("TECHNIQUE_NOT_AUTHORIZED");
  }
  if (scope.target.type !== "WORKSPACE" && input.task.targetId !== scope.target.id) {
    reasons.push("TASK_TARGET_OUT_OF_SCOPE");
  }
  if (scope.reviewerApproval.required && scope.reviewerApproval.approvedBy.length === 0) {
    reasons.push("REVIEWER_APPROVAL_REQUIRED");
  }
  if (scope.constraints.persistRawPayloads !== false) {
    reasons.push("RAW_PAYLOAD_PERSISTENCE_FORBIDDEN");
  }
  if (scope.constraints.networkAccess !== "disabled" && scope.safeMode !== "sandbox_repro") {
    reasons.push("NETWORK_ACCESS_REQUIRES_SANDBOX_REPRO");
  }
  if (proofCountForScope(input.workspace, scope.scopeId) >= scope.constraints.maxTasks) {
    reasons.push("SCOPE_TASK_LIMIT_REACHED");
  }
  return authorizationDecisionSchema.parse({
    ok: reasons.length === 0,
    scopeId: scope.scopeId,
    reasons
  });
}

