export function assertSigningKey(signingKey: string): void {
  const key = signingKey?.trim() ?? "";
  // Check known-weak values first so the error names the actual problem.
  if (key === "amc-default-key" || key === "default" || key === "changeme") {
    throw new Error(
      `Refusing to sign with the well-known key '${key}'. Supply a per-agent secret.`
    );
  }
  if (key.length < 16) {
    throw new Error(
      "A signing key of at least 16 characters is required; attestations signed with a short or empty key are forgeable."
    );
  }
}

export function validLegacyIndustryPackLicenseKey(
  value: string,
  env: NodeJS.ProcessEnv = process.env,
): boolean {
  if (!isLegacyIndustryPackLicenseKey(value)) {
    return false;
  }
  const digest = sha256Hex(value.trim());
  const allowlist = (env.AMC_INDUSTRY_PACKS_LEGACY_KEY_SHA256_ALLOWLIST ?? "")
    .split(",")
    .map((entry) => entry.trim().toLowerCase())
    .filter((entry) => /^[a-f0-9]{64}$/.test(entry));
  return allowlist.some((allowedDigest) => constantTimeEqual(allowedDigest, digest));
}

