export function extractToolCallRequests(text: string): Array<Record<string, unknown>> {
  const out: Array<Record<string, unknown>> = [];
  const matches = text.match(TOOL_JSON_RE) ?? [];
  for (const match of matches) {
    try {
      const parsed = JSON.parse(match) as Record<string, unknown>;
      if (typeof parsed.tool === "string" && typeof parsed.action === "string") {
        out.push(parsed);
      }
    } catch {
      // ignore invalid JSON chunk
    }
  }
  return out;
}

export function argvAllowed(tool: ToolDefinition, argv: string[]): { ok: boolean; reason?: string } {
  const joined = argv.join(" ");
  const denyRegex = tool.deny?.argvRegexDenylist ?? [];
  for (const pattern of denyRegex) {
    try {
      const re = new RegExp(pattern, "i");
      if (re.test(joined)) {
        return { ok: false, reason: `argv blocked by deny pattern: ${pattern}` };
      }
    } catch {
      continue;
    }
  }
  return { ok: true };
}

