export function nativeToolMatchesCapability(tool: ToolDefinition, capability: NativeToolCapability): boolean {
  if (tool.name !== capability.name || tool.actionClass !== capability.actionClass) return false;
  const actual = tool.context;
  const expected = capability.context;
  if (expected?.kind !== "mcp") return actual === undefined || actual.kind === "native";
  return actual?.kind === "mcp" && actual.server.id === expected.server.id
    && actual.server.name === expected.server.name && actual.server.version === expected.server.version
    && actual.server.transport === expected.server.transport;
}

export function buildAutoAnswerRules(): AutoAnswerRule[] {
  const rules = questionBank.map((question) => {
    const requiredEvidenceTypes = uniqueSorted(
      question.gates.flatMap((gate) => gate.requiredEvidenceTypes).filter((item): item is EvidenceEventType => Boolean(item))
    );
    const minEvents = Math.max(1, ...question.gates.map((gate) => Math.max(1, gate.minEvents)));
    const minDistinctDays = Math.max(1, ...question.gates.map((gate) => Math.max(1, gate.minDistinctDays)));
    return {
      questionId: question.id,
      requiredEvidenceTypes,
      minEvents,
      minDistinctDays
    } satisfies AutoAnswerRule;
  });
  return rules.sort((a, b) => a.questionId.localeCompare(b.questionId));
}

export function verifyPromptSignatureObject(params: {
  digestHex: string;
  signature: unknown;
  signerPub: string;
}): boolean {
  const parsed = orgSignatureSchema.safeParse(params.signature);
  if (!parsed.success) {
    return false;
  }
  if (parsed.data.envelope) {
    try {
      if (parsed.data.signature !== parsed.data.envelope.sigB64) {
        return false;
      }
      return verifySignatureEnvelope(params.digestHex, parsed.data.envelope, {
        trustedPublicKeys: [params.signerPub],
        requireTrustedKey: true
      });
    } catch {
      return false;
    }
  }
  return verifyHexDigestAny(params.digestHex, parsed.data.signature, [params.signerPub]);
}

