export function validateOrgGraph(config: OrgConfig): {
  valid: boolean;
  errors: string[];
} {
  const errors: string[] = [];
  const nodeById = new Map<string, { parentId: string | null }>();

  for (const node of config.nodes) {
    if (nodeById.has(node.id)) {
      errors.push(`duplicate node id: ${node.id}`);
    }
    nodeById.set(node.id, { parentId: node.parentId });
  }

  for (const node of config.nodes) {
    if (node.parentId !== null && !nodeById.has(node.parentId)) {
      errors.push(`node '${node.id}' references missing parent '${node.parentId}'`);
    }
    if (node.parentId === node.id) {
      errors.push(`node '${node.id}' cannot parent itself`);
    }
  }

  // cycle detection
  const visiting = new Set<string>();
  const visited = new Set<string>();

  const visit = (id: string): void => {
    if (visited.has(id)) {
      return;
    }
    if (visiting.has(id)) {
      errors.push(`cycle detected at node '${id}'`);
      return;
    }
    visiting.add(id);
    const parentId = nodeById.get(id)?.parentId ?? null;
    if (parentId && nodeById.has(parentId)) {
      visit(parentId);
    }
    visiting.delete(id);
    visited.add(id);
  };

  for (const node of config.nodes) {
    visit(node.id);
  }

  for (const membership of config.memberships) {
    if (membership.weight <= 0) {
      errors.push(`membership weight must be positive for agent '${membership.agentId}'`);
    }
    for (const nodeId of membership.nodeIds) {
      if (!nodeById.has(nodeId)) {
        errors.push(`membership references missing node '${nodeId}' for agent '${membership.agentId}'`);
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

export function weightedTrimmedMean(points: WeightedPoint[], trimRatio = 0.1): number {
  const rows = sanitize(points);
  if (rows.length === 0) {
    return 0;
  }
  const total = totalWeight(rows);
  if (total <= 0) {
    return 0;
  }
  const trim = Math.max(0, Math.min(0.49, trimRatio));
  const lower = total * trim;
  const upper = total * (1 - trim);
  let acc = 0;
  let weightedSum = 0;
  let usedWeight = 0;
  for (const row of rows) {
    const start = acc;
    const end = acc + row.weight;
    acc = end;
    const overlapStart = Math.max(start, lower);
    const overlapEnd = Math.min(end, upper);
    const overlap = Math.max(0, overlapEnd - overlapStart);
    if (overlap > 0) {
      weightedSum += row.value * overlap;
      usedWeight += overlap;
    }
  }
  if (usedWeight <= 0) {
    return weightedMean(rows);
  }
  return weightedSum / usedWeight;
}

