export function parseDshSession(text: string): ParsedDshSession {
  if (Buffer.byteLength(text, "utf8") > DSH_IMPORT_LIMITS.bytes) refuse("document exceeds 32 MiB.");
  const rows: unknown[] = [];
  for (const [index, line] of text.split(/\r?\n/).entries()) {
    if (!line.trim()) continue;
    if (Buffer.byteLength(line, "utf8") > DSH_IMPORT_LIMITS.lineBytes) refuse(`line ${index + 1} exceeds 4 MiB.`);
    if (rows.length > DSH_IMPORT_LIMITS.events) refuse("too many events.");
    let row: unknown;
    try { row = JSON.parse(line); } catch { refuse(`malformed JSON at line ${index + 1}; torn tails are not silently repaired.`); }
    boundedJson(row); rows.push(row);
  }
  return parseRows(rows);
}

export function inferExecutiveBriefFormat(outputPath: string | undefined, format: string | undefined): ExecutiveBriefFormat {
  if (format !== undefined) {
    const normalized = format.trim().toLowerCase();
    if (normalized === "html" || normalized === "markdown") return normalized;
    if (normalized === "md") return "markdown";
    throw new Error("--format must be html or markdown.");
  }
  const ext = outputPath ? extname(outputPath).toLowerCase() : "";
  return ext === ".md" || ext === ".markdown" ? "markdown" : "html";
}

